constexpr int G=64,PART=8192;constexpr float SENT=-777.f;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
void guard(bool initial=false){const char*v=getenv("CUDA_VISIBLE_DEVICES");if(!v||(strcmp(v,"6")&&strcmp(v,"5,6")))exit(3);if(!strcmp(v,"6"))return;FILE*f=popen("nvidia-smi -i 5 --query-compute-apps=pid --format=csv,noheader,nounits","r");if(!f)exit(3);char line[128];while(fgets(line,sizeof(line),f)){char*end;long pid=strtol(line,&end,10);if(end==line&&strspn(line," \n\r\t")!=strlen(line))exit(3);if(pid>0&&pid!=getpid()){fprintf(stderr,"ExternalGPU5PID %ld\n",pid);exit(3);}}if(pclose(f)!=0)exit(3);if(initial){f=popen("nvidia-smi -i 5 --query-gpu=memory.used --format=csv,noheader,nounits","r");if(!f||!fgets(line,sizeof(line),f)||strtol(line,nullptr,10)!=0)exit(3);if(pclose(f)!=0)exit(3);}}
uint64_t bits(float x){uint32_t u;memcpy(&u,&x,4);return u;}uint64_t bits(double x){uint64_t u;memcpy(&u,&x,8);return u;}
float value(int i,int flavor){if(flavor==0)return float(i&255)/512.f;uint32_t x=uint32_t(i)*1664525u+1013904223u;x^=x>>16;x*=2246822519u;x^=x>>13;return float(x)*0x1p-32f;}
std::vector<uint64_t>load(int g){std::ifstream in(std::string(SMD_ROOT)+"/oracle_g"+std::to_string(g)+"_u64.bin",std::ios::binary|std::ios::ate);if(!in)exit(4);size_t bytes=in.tellg();if(bytes%8)exit(5);std::vector<uint64_t>v(bytes/8);in.seekg(0);if(!in.read((char*)v.data(),bytes))exit(6);return v;}
struct Plan{int d,n,offset;cudaStream_t stream;float *hin,*hout,*checkin,*checkout,*din,*dout;};struct Case{int n,flavor;std::vector<Plan>plans;};
void poison(Case&c){for(auto&p:c.plans){ck(cudaSetDevice(p.d));memset(p.hout+G,255,PART*4);ck(cudaMemsetAsync(p.din+G,255,p.n*4,p.stream));ck(cudaMemsetAsync(p.dout+G,255,PART*4,p.stream));ck(cudaStreamSynchronize(p.stream));}}
void pipeline(Case&c){for(auto&p:c.plans){ck(cudaSetDevice(p.d));ck(cudaMemcpyAsync(p.din+G,p.hin+G,p.n*4,cudaMemcpyHostToDevice,p.stream));reduceKernel<<<32,256,0,p.stream>>>(p.dout+G,p.din+G,p.n);ck(cudaGetLastError());ck(cudaMemcpyAsync(p.hout+G,p.dout+G,PART*4,cudaMemcpyDeviceToHost,p.stream));}for(auto&p:c.plans){ck(cudaSetDevice(p.d));ck(cudaStreamSynchronize(p.stream));}}
int main(int argc,char**argv){guard(true);if(argc!=2)return 7;int g=atoi(argv[1]),actual;ck(cudaGetDeviceCount(&actual));if(g!=actual||(g!=1&&g!=2))return 8;for(int d=0;d<g;d++){cudaDeviceProp prop;ck(cudaGetDeviceProperties(&prop,d));char pci[64];ck(cudaDeviceGetPCIBusId(pci,sizeof(pci),d));printf("STUDY_DEVICE visible=%d pci=%s uuid=GPU-",d,pci);for(int i=0;i<16;i++){if(i==4||i==6||i==8||i==10)printf("-");printf("%02x",(unsigned char)prop.uuid.bytes[i]);}printf("\n");}std::ifstream maps("/proc/self/maps");std::string line;while(std::getline(maps,line))if(line.find("libcudart")!=std::string::npos)printf("LOADED_LIBRARY_MAP %s\n",line.c_str());
 auto oracle=load(g);std::vector<Case>cases;size_t prefix=1;for(auto spec:{std::pair<int,int>{3,1},{8193,1},{131079,1},{33554432,0}}){Case c;c.n=spec.first;c.flavor=spec.second;int offset=0;prefix+=2+c.n;for(int d=0;d<g;d++){Plan p;p.d=d;p.n=c.n/g+(d<c.n%g);p.offset=offset;offset+=p.n;ck(cudaSetDevice(d));ck(cudaStreamCreate(&p.stream));ck(cudaMallocHost(&p.hin,(p.n+2*G)*4));ck(cudaMallocHost(&p.checkin,(p.n+2*G)*4));ck(cudaMallocHost(&p.hout,(PART+2*G)*4));ck(cudaMallocHost(&p.checkout,(PART+2*G)*4));std::fill(p.hin,p.hin+p.n+2*G,SENT);std::fill(p.hout,p.hout+PART+2*G,SENT);for(int i=0;i<p.n;i++)p.hin[G+i]=value(p.offset+i,c.flavor);ck(cudaMalloc(&p.din,(p.n+2*G)*4));ck(cudaMalloc(&p.dout,(PART+2*G)*4));ck(cudaMemcpy(p.din,p.hin,(p.n+2*G)*4,cudaMemcpyDefault));ck(cudaMemcpy(p.dout,p.hout,(PART+2*G)*4,cudaMemcpyDefault));c.plans.push_back(p);}cases.push_back(c);}std::vector<uint64_t>payload;payload.reserve(prefix+oracle.size());std::vector<uint64_t>suffix;suffix.reserve(oracle.size());for(auto&c:cases){poison(c);pipeline(c);}for(int trial=1;trial<=5;trial++){guard();payload.clear();suffix.clear();payload.push_back(bits(float(cases.size())));double total=0;bool ok=true;std::vector<double>times;for(auto&c:cases){poison(c);auto start=std::chrono::steady_clock::now();pipeline(c);double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();total+=elapsed;times.push_back(elapsed);payload.push_back(bits(float(c.n)));payload.push_back(bits(float(c.flavor)));std::vector<float>locals;double cpu=0;for(auto&p:c.plans){ck(cudaSetDevice(p.d));ck(cudaMemcpy(p.checkin,p.din,(p.n+2*G)*4,cudaMemcpyDefault));ck(cudaMemcpy(p.checkout,p.dout,(PART+2*G)*4,cudaMemcpyDefault));for(int i=0;i<p.n;i++){float v=p.checkin[G+i];ok &=bits(v)==bits(p.hin[G+i])&&v==value(p.offset+i,c.flavor);payload.push_back(bits(v));cpu+=p.hin[G+i];}float sum=0;for(int i=0;i<PART;i++){float v=p.hout[G+i];suffix.push_back(bits(v));sum+=v;}for(int i=0;i<PART;i++)suffix.push_back(bits(p.checkout[G+i]));suffix.push_back(bits(sum));locals.push_back(sum);for(float*a:{p.hin,p.checkin,p.hout,p.checkout}){int n=(a==p.hin||a==p.checkin)?p.n:PART;for(int i=0;i<G;i++){ok &=a[i]==SENT;suffix.push_back(bits(a[i]));}for(int i=0;i<G;i++){ok &=a[G+n+i]==SENT;suffix.push_back(bits(a[G+n+i]));}}}float gpu=0;for(float v:locals)gpu+=v;double diff=fabs(cpu-double(gpu))/fabs(cpu);ok &=std::isfinite(diff)&&diff<1e-5;suffix.push_back(bits(gpu));suffix.push_back(bits(cpu));suffix.push_back(bits(diff));}ok &=suffix==oracle;payload.insert(payload.end(),suffix.begin(),suffix.end());std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*8);out.close();guard();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum4_async_pinned_H2D_stridedpartials_D2H_all_stream_completion\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":%d,\"active_devices\":%d,\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),ok?0:1,4*g,g);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 9;}for(auto&c:cases)for(auto&p:c.plans){ck(cudaSetDevice(p.d));ck(cudaStreamSynchronize(p.stream));ck(cudaFree(p.din));ck(cudaFree(p.dout));ck(cudaFreeHost(p.hin));ck(cudaFreeHost(p.hout));ck(cudaFreeHost(p.checkin));ck(cudaFreeHost(p.checkout));ck(cudaStreamDestroy(p.stream));}return 0;}
